def insert_before_sources(text, claim_id, addition):
    marker = u"### %s " % claim_id
    i = text.find(marker)
    assert i >= 0, claim_id
    j = text.find(u"\nLast touched:", i)
    assert j >= 0, claim_id
    s = text.rfind(u"\nSources:", i, j)
    assert s >= 0, claim_id
    return text[:s] + u"\n" + addition.rstrip() + text[s:]


